-- One row per submitted content item. The id is generated by the application (UUID v4)
-- so it is known before the insert and can be reused by the outbox event in Phase 2.
--
-- Never edit this file once applied: Flyway checksums it. Changes go in a new V<n> file.
CREATE TABLE submissions (
    id            UUID          PRIMARY KEY,
    source        VARCHAR(255)  NOT NULL,
    title         VARCHAR(500),
    content_type  VARCHAR(100)  NOT NULL,
    content       TEXT          NOT NULL,
    -- VARCHAR + CHECK instead of a Postgres ENUM: each new status is a small migration
    -- that replaces this constraint, and JPA maps it with EnumType.STRING.
    status        VARCHAR(32)   NOT NULL
                  CONSTRAINT submissions_status_chk CHECK (status IN ('RECEIVED')),
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    -- Kept current by the application on update, not by a trigger.
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT now()
);
